package com.wesbos.homehq;

import android.graphics.*;
import android.media.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

/** Bounded GIF-to-muted-H.264 conversion, with no source metadata or audio. */
final class GifClip {
  private static int word(byte[] b,int offset)throws IOException {if(offset+1>=b.length)throw new IOException("Incomplete GIF");return (b[offset]&255)|((b[offset+1]&255)<<8);}
  private static int blocks(byte[] b,int offset)throws IOException {while(offset<b.length){int size=b[offset++]&255;if(size==0)return offset;if(offset+size>b.length)break;offset+=size;}throw new IOException("Incomplete GIF data");}
  static void validate(byte[] bytes)throws IOException {if(bytes.length<13)throw new IOException("GIF header unavailable");int width=word(bytes,6),height=word(bytes,8);long pixels=(long)width*height;if(width<1||height<1||pixels>2000000)throw new IOException("GIF canvas exceeds limit");int offset=13,frames=0;if((bytes[10]&128)!=0)offset+=3*(1<<((bytes[10]&7)+1));while(offset<bytes.length){int marker=bytes[offset++]&255;if(marker==0x3b)return;if(marker==0x21){if(offset>=bytes.length)break;offset++;offset=blocks(bytes,offset);}else if(marker==0x2c){if(offset+9>bytes.length)break;int w=word(bytes,offset+4),h=word(bytes,offset+6);if(w<1||h<1||(long)w*h>pixels)throw new IOException("GIF frame exceeds canvas");int packed=bytes[offset+8]&255;offset+=9;if((packed&128)!=0)offset+=3*(1<<((packed&7)+1));if(offset>=bytes.length)break;offset++;offset=blocks(bytes,offset);if(++frames>150||pixels*frames>16000000L)throw new IOException("GIF decoded-frame budget exceeded");}else throw new IOException("GIF structure unsupported");}throw new IOException("Incomplete GIF");}
  static void encode(byte[] source,File target,BooleanSupplier active) throws Exception {
    validate(source);Movie movie=Movie.decodeByteArray(source,0,source.length);if(movie==null||movie.width()<1||movie.height()<1||movie.width()>20000||movie.height()>20000)throw new IOException("GIF unsupported");int duration=movie.duration();if(duration<=0)duration=1000;if(duration>30000)throw new IOException("GIF longer than 30 seconds");
    double scale=Math.min(1,720.0/Math.max(movie.width(),movie.height()));int width=Math.max(320,((int)(movie.width()*scale)/2)*2),height=Math.max(240,((int)(movie.height()*scale)/2)*2),fps=15,total=(int)Math.ceil(duration*fps/1000.0);
    MediaCodec codec=MediaCodec.createEncoderByType("video/avc");MediaMuxer muxer=null;Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);int[] pixels=new int[width*height];boolean started=false;int track=-1;
    try{MediaFormat format=MediaFormat.createVideoFormat("video/avc",width,height);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);format.setInteger(MediaFormat.KEY_BIT_RATE,1200000);format.setInteger(MediaFormat.KEY_FRAME_RATE,fps);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);codec.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);codec.start();muxer=new MediaMuxer(target.getAbsolutePath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int sent=0;boolean ended=false;long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(90);
      while(!ended){if(!active.getAsBoolean()||System.nanoTime()>deadline)throw new IOException("Conversion cancelled");if(sent<=total){int input=codec.dequeueInputBuffer(10000);if(input>=0){if(sent==total){codec.queueInputBuffer(input,0,0,sent*1000000L/fps,MediaCodec.BUFFER_FLAG_END_OF_STREAM);sent++;}else{canvas.drawColor(Color.rgb(238,232,221));movie.setTime(Math.min(duration-1,sent*1000/fps));canvas.save();float factor=Math.min((float)width/movie.width(),(float)height/movie.height());canvas.translate((width-movie.width()*factor)/2,(height-movie.height()*factor)/2);canvas.scale(factor,factor);movie.draw(canvas,0,0);canvas.restore();bitmap.getPixels(pixels,0,width,0,0,width,height);Image image=codec.getInputImage(input);if(image==null)throw new IOException("Flexible YUV input unavailable");writeYuv(image,pixels,width,height);image.close();codec.queueInputBuffer(input,0,width*height*3/2,sent*1000000L/fps,0);sent++;}}}
        int output=codec.dequeueOutputBuffer(info,10000);if(output==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(started)throw new IOException("Encoder changed format");track=muxer.addTrack(codec.getOutputFormat());muxer.start();started=true;}else if(output>=0){ByteBuffer bytes=codec.getOutputBuffer(output);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0){if(!started)throw new IOException("Encoder format unavailable");bytes.position(info.offset);bytes.limit(info.offset+info.size);muxer.writeSampleData(track,bytes,info);}ended=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(output,false);}
      }
    }finally{bitmap.recycle();try{codec.stop();}catch(Exception ignored){}codec.release();if(muxer!=null){try{if(started)muxer.stop();}finally{muxer.release();}}}
  }
  private static void writeYuv(Image image,int[] pixels,int width,int height){Image.Plane[] planes=image.getPlanes();for(int y=0;y<height;y++)for(int x=0;x<width;x++){int color=pixels[y*width+x],r=(color>>16)&255,g=(color>>8)&255,b=color&255;int luma=((66*r+129*g+25*b+128)>>8)+16;planes[0].getBuffer().put(y*planes[0].getRowStride()+x*planes[0].getPixelStride(),(byte)Math.max(0,Math.min(255,luma)));if((x&1)==0&&(y&1)==0){int u=((-38*r-74*g+112*b+128)>>8)+128,v=((112*r-94*g-18*b+128)>>8)+128;planes[1].getBuffer().put((y/2)*planes[1].getRowStride()+(x/2)*planes[1].getPixelStride(),(byte)Math.max(0,Math.min(255,u)));planes[2].getBuffer().put((y/2)*planes[2].getRowStride()+(x/2)*planes[2].getPixelStride(),(byte)Math.max(0,Math.min(255,v)));}}}
}
